from pathlib import Path
import re

MAIN=Path('web/src/main.js')
CSS=Path('web/src/styles.css')
PKG=Path('web/package.json')
s=MAIN.read_text(encoding='utf-8')

pattern=r"function startsit\(\)\{.*?\}\nfunction about\(\)"
replacement=r'''function startSitRow(id){const p=st.players?.[id]||{},m=model(id,p),av=m.availability||availabilityInfo(id,p,st.week,1),avgLabel=m.avgSource==='actual'?(m.avgGames?`${m.avgGames} GP`:'Actual'):m.avgSource==='projected'?'Projected':'—',range=m.floor!=null&&m.ceiling!=null?m.ceiling-m.floor:null,vsAvg=m.projection!=null&&m.avg!=null?m.projection-m.avg:null;return{id,p,m,av,avgLabel,range,vsAvg}}
function startSitDecision(rows){if(rows.length<2)return null;const ranked=[...rows].sort((a,b)=>(b.m.projection??-999)-(a.m.projection??-999)),top=ranked[0],second=ranked[1],gap=top.m.projection!=null&&second.m.projection!=null?top.m.projection-second.m.projection:null,floorGap=top.m.floor!=null&&second.m.floor!=null?top.m.floor-second.m.floor:null,ceilGap=top.m.ceiling!=null&&second.m.ceiling!=null?top.m.ceiling-second.m.ceiling:null,avgGap=top.m.avg!=null&&second.m.avg!=null?top.m.avg-second.m.avg:null,overlap=top.m.floor!=null&&top.m.ceiling!=null&&second.m.floor!=null&&second.m.ceiling!=null?Math.max(0,Math.min(top.m.ceiling,second.m.ceiling)-Math.max(top.m.floor,second.m.floor)):null;let level='Close call';if(gap!=null&&gap>=4)level='Strong lean';else if(gap!=null&&gap>=2)level='Moderate lean';if(top.av.factor<1||second.av.factor<1)level=gap!=null&&gap>=4?'Moderate lean':'Close call';const reasons=[];if(gap!=null)reasons.push(`${pname(top.id)} projects ${f(Math.abs(gap))} points higher than ${pname(second.id)} for Week ${st.week}.`);if(floorGap!=null&&Math.abs(floorGap)>=1)reasons.push(`${pname(floorGap>=0?top.id:second.id)} has the stronger modeled floor by ${f(Math.abs(floorGap))} points.`);if(ceilGap!=null&&Math.abs(ceilGap)>=1)reasons.push(`${pname(ceilGap>=0?top.id:second.id)} has the higher ceiling by ${f(Math.abs(ceilGap))} points.`);if(avgGap!=null&&Math.abs(avgGap)>=1)reasons.push(`${pname(avgGap>=0?top.id:second.id)} has the better current-season scoring rate by ${f(Math.abs(avgGap))} PPG.`);if(top.av.factor<1||second.av.factor<1){const risk=[top,second].filter(x=>x.av.factor<1).map(x=>`${pname(x.id)} ${Math.round(x.av.factor*100)}%`).join(', ');reasons.push(`Availability risk matters here: ${risk}.`)}if(overlap!=null&&overlap>=4)reasons.push(`Their floor-ceiling ranges overlap by ${f(overlap)} points, so the outcome is less certain than the raw projection gap alone.`);return{ranked,top,second,gap,floorGap,ceilGap,avgGap,overlap,level,reasons}}
function startSitCard(x,rank,decision){const isTop=decision?.top?.id===x.id,av=x.av,projSub=x.m.projectionWasOverridden&&x.m.rawProjection!=null?`Base ${f(x.m.rawProjection)} before availability`:`${conf(x.m.confidence)} confidence`,trend=x.vsAvg==null?'—':`${x.vsAvg>=0?'+':''}${f(x.vsAvg)}`,status=av.label||'Available';return`<div class="startsit-card ${isTop?'preferred':''} ${av.factor<=0?'unavailable':''}"><div class="startsit-rank">${decision?(isTop?'PREFERRED':`#${rank}`):`#${rank}`}</div><div class="startsit-player"><img src="${assetImage(x.id,x.p)}" alt="" onerror="this.style.display='none'"><div><strong>${esc(pname(x.id))}</strong><span>${esc(x.p.position||'')} · ${esc(x.p.team||'FA')} · ${esc(x.m.opp||'Matchup unavailable')}</span>${availabilityChip(av)}</div></div><div class="startsit-projection"><div><span>Week ${st.week}</span><strong>${f(x.m.projection)}</strong><small>${esc(projSub)}</small></div><div><span>Season PPG</span><strong>${f(x.m.avg)}</strong><small>${esc(x.avgLabel)}</small></div></div><div class="startsit-detail-grid"><div><span>Floor</span><strong>${f(x.m.floor)}</strong></div><div><span>Ceiling</span><strong>${f(x.m.ceiling)}</strong></div><div><span>Vs season</span><strong>${trend}</strong></div><div><span>Range width</span><strong>${f(x.range)}</strong></div><div><span>Availability</span><strong>${Math.round(av.factor*100)}%</strong></div><div><span>Status</span><strong>${esc(status)}</strong></div></div><div class="startsit-actions"><button class="btn btn-ghost" data-player="${esc(x.id)}">News + analysis</button><button class="btn btn-ghost" data-remove="${esc(x.id)}">Remove</button></div></div>`}
function startsit(){const rows=st.compare.map(startSitRow),decision=startSitDecision(rows),ranked=decision?.ranked||rows;const summary=decision?`<div class="startsit-summary card"><div class="startsit-summary-top"><div><div class="eyebrow">${esc(decision.level)}</div><h2>Start ${esc(pname(decision.top.id))}</h2><p>Over ${esc(pname(decision.second.id))}${decision.gap!=null?` by a modeled ${f(decision.gap)} points`:''}.</p></div><div class="startsit-edge"><span>Projection edge</span><strong>${decision.gap!=null?`+${f(decision.gap)}`:'—'}</strong></div></div><div class="startsit-factors">${decision.reasons.map(x=>`<div><span>•</span><p>${esc(x)}</p></div>`).join('')}</div></div>`:st.compare.length===1?'<div class="empty">Add at least one more player to generate a start/sit recommendation.</div>':'';const leagueNote=st.league?`Season PPG uses ${esc(st.league.name)} scoring where the Sleeper stat feed supports it. Weekly projections come from Fantasy Model.`:'Connect/open a Sleeper league for league-scored Season PPG; weekly projections still come from Fantasy Model.';return layout('Start/Sit Tool',`<div class="toolbar"><div><h1 class="page-title">Start/Sit Tool</h1><p class="page-subtitle">Compare 2–4 players with projection edge, floor/ceiling risk, season production, matchup and availability context.</p></div><div style="margin-left:auto">${weekSel()}</div></div><div class="card card-pad"><input id="search" class="input" placeholder="Search player…"><div id="results" class="asset-list" style="margin-top:9px"></div></div>${summary}<div class="startsit-grid">${ranked.length?ranked.map((x,i)=>startSitCard(x,i+1,decision)).join(''):'<div class="empty">Add players to compare.</div>'}</div>${rows.length?`<p class="muted small startsit-source">${esc(leagueNote)} Injury and IR/Out overrides are applied before the recommendation is ranked.</p>`:''}`)}
function about()'''
ns,count=re.subn(pattern,replacement,s,count=1,flags=re.S)
if count!=1:
    raise SystemExit(f'startsit replacement count {count}')
s=ns.replace("if(st.route==='startsit')players()","if(st.route==='startsit'){await Promise.all([players(),loadSeasonStats()]);render()}",1)
s=ns.replace("if(st.route==='live')liveLoad()}","if(st.route==='live')liveLoad();if(st.route==='startsit'){await Promise.all([players(),loadSeasonStats()]);render()}}",1)
MAIN.write_text(ns,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
css += r'''

/* Web 1.3.8 — informative Start/Sit decision tool */
.startsit-summary{padding:18px;margin-top:14px;border-color:rgba(182,255,69,.28);background:linear-gradient(135deg,rgba(182,255,69,.08),rgba(13,19,16,.96))}.startsit-summary-top{display:flex;justify-content:space-between;gap:18px;align-items:center}.startsit-summary h2{margin:3px 0 4px;font-size:24px}.startsit-summary p{margin:0;color:var(--muted)}.startsit-edge{min-width:120px;text-align:right}.startsit-edge span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.07em}.startsit-edge strong{display:block;font-size:30px;color:var(--accent);margin-top:2px}.startsit-factors{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:14px}.startsit-factors>div{display:grid;grid-template-columns:12px 1fr;gap:5px;padding:9px 10px;border:1px solid rgba(36,51,43,.72);border-radius:9px;background:rgba(255,255,255,.015)}.startsit-factors span{color:var(--accent);font-weight:900}.startsit-factors p{font-size:12px;line-height:1.4;color:#dce8df}.startsit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-top:14px}.startsit-card{position:relative;padding:15px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(180deg,rgba(18,26,22,.98),rgba(13,19,16,.98));min-width:0}.startsit-card.preferred{border-color:rgba(182,255,69,.4);box-shadow:0 0 0 1px rgba(182,255,69,.08),var(--shadow)}.startsit-card.unavailable{opacity:.72}.startsit-rank{color:var(--muted);font-size:9px;font-weight:900;letter-spacing:.1em}.startsit-card.preferred .startsit-rank{color:var(--accent)}.startsit-player{display:flex;align-items:center;gap:10px;margin:8px 0 12px}.startsit-player img{width:54px;height:54px;border-radius:12px;object-fit:cover;object-position:center 15%;background:#17211c}.startsit-player>div{display:grid;min-width:0}.startsit-player>div>strong{font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.startsit-player>div>span:not(.availability-chip){color:var(--muted);font-size:11px;margin-top:3px}.startsit-projection{display:grid;grid-template-columns:1fr 1fr;gap:8px}.startsit-projection>div{padding:11px;border:1px solid rgba(36,51,43,.8);border-radius:10px;background:rgba(255,255,255,.018)}.startsit-projection span,.startsit-projection small{display:block;color:var(--muted);font-size:9px}.startsit-projection strong{display:block;font-size:22px;margin:3px 0}.startsit-detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.startsit-detail-grid>div{padding:8px;border:1px solid rgba(36,51,43,.68);border-radius:9px}.startsit-detail-grid span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.05em}.startsit-detail-grid strong{display:block;font-size:12px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.startsit-actions{display:flex;gap:7px;margin-top:12px}.startsit-actions .btn{flex:1;font-size:11px;padding:8px}.startsit-source{margin-top:12px;line-height:1.5}@media(max-width:700px){.startsit-summary-top{align-items:flex-start}.startsit-factors{grid-template-columns:1fr}.startsit-grid{grid-template-columns:1fr}.startsit-detail-grid{grid-template-columns:repeat(2,1fr)}.startsit-edge strong{font-size:25px}}
'''
CSS.write_text(css,encoding='utf-8')

p=PKG.read_text(encoding='utf-8')
if '"version": "1.3.7"' not in p:
    raise SystemExit('expected Web 1.3.7')
p=p.replace('"version": "1.3.7"','"version": "1.3.8"',1)
PKG.write_text(p,encoding='utf-8')
print('Patched Web 1.3.8: informative Start/Sit tool')
